fn gcd_calc(mut m: u32, mut n: u32) -> u32 {
    // Euclidean algorithm (modulo version)
    // In each step, we replace (m, n) with (n, m % n) until n becomes zero.
    // At that point, m is the GCD.
    while n != 0 {
        let r = m % n;
        m = n;
        n = r;
    }
    m
}

